import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Both 'interval' and 'duration' must be greater than zero.")

    data = []
    start_time = time.time()
    end_time = start_time + duration

    while time.time() < end_time:
        current_time = time.time()
        timestamp = time.strftime('%Y-%m-%d %H:%M:%S', time.localtime(current_time))

        system_platform = platform.system()
        if system_platform == "Windows":
            try:
                output = subprocess.check_output("wmic cpu get loadpercentage", shell=True, text=True)
                lines = output.strip().split('\n')
                if len(lines) >= 2:
                    cpu_usage = lines[1].strip()
                    if cpu_usage.isdigit():
                        cpu_usage = float(cpu_usage)
                    else:
                        cpu_usage = 0.0
                else:
                    cpu_usage = 0.0
            except subprocess.CalledProcessError:
                cpu_usage = 0.0
        else:
            try:
                output = subprocess.check_output("top -bn1 | grep \"Cpu(s)\"", shell=True, text=True)
                parts = output.split(',')
                idle_cpu = None
                for part in parts:
                    if 'id' in part:
                        idle_cpu = float(part.split()[0])
                        break
                if idle_cpu is not None:
                    cpu_usage = 100.0 - idle_cpu
                else:
                    cpu_usage = 0.0
            except subprocess.CalledProcessError:
                cpu_usage = 0.0

        data.append({'timestamp': timestamp, 'cpu_usage': cpu_usage})

        sleep_time = interval - (time.time() - current_time)
        if sleep_time > 0:
            time.sleep(sleep_time)

    try:
        with open(LOGFILE_PATH, 'w') as log_file:
            json.dump(data, log_file, indent=4)
        return LOGFILE_PATH
    except IOError:
        return None

